{"source": "def investigate(context, acquire):
    history = acquire("history")

    def simulate(actions, put_mode, trigger, channel_mode):
        committed = {}
        working = None
        tx_conn = None
        main_total = 0
        other_total = 0
        main_last = 0
        other_last = 0

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if conn not in ('main', 'other'):
                return None
            if op == 'begin':
                if tx_conn is not None:
                    return None
                tx_conn = conn
                working = dict(committed)
            elif op == 'commit':
                if tx_conn != conn:
                    return None
                committed = working
                tx_conn = None
                working = None
            elif op == 'rollback':
                if tx_conn != conn:
                    return None
                tx_conn = None
                working = None
            elif op in ('put', 'update', 'delete'):
                key = act.get('key')
                if not isinstance(key, str) or not key:
                    return None
                if op == 'put':
                    val = act.get('value')
                    if not isinstance(val, int) or val < 0 or val > 1000000:
                        return None
                if tx_conn == conn:
                    view = working
                else:
                    view = committed
                direct = 0
                trig = 0
                if op == 'put':
                    if key in view:
                        if put_mode == 0:
                            direct = 0
                            trig = 0
                        elif put_mode == 1:
                            direct = 1
                            trig = 1 if trigger else 0
                            del view[key]
                            view[key] = val
                        else:
                            direct = 1
                            trig = 0
                            view[key] = val
                    else:
                        direct = 1
                        trig = 1 if trigger else 0
                        view[key] = val
                elif op == 'update':
                    if key in view:
                        direct = 1
                        trig = 0
                        view[key] = act.get('value')
                    else:
                        direct = 0
                        trig = 0
                elif op == 'delete':
                    if key in view:
                        direct = 1
                        trig = 0
                        del view[key]
                    else:
                        direct = 0
                        trig = 0
                if conn == 'main':
                    main_last = direct
                    main_total += direct + trig
                else:
                    other_last = direct
                    other_total += direct + trig
            else:
                return None

        committed_count = len(committed)
        committed_sum = sum(committed.values())
        if channel_mode == 0:
            channel = main_last
        elif channel_mode == 1:
            channel = main_total
        else:
            channel = main_total + other_total
        return (channel, committed_count, committed_sum)

    consistent = []
    for put_mode in range(3):
        for trigger in range(2):
            for channel_mode in range(3):
                ok = True
                for rec in history:
                    actions = rec.get('actions', [])
                    obs = rec.get('observed', {})
                    sim = simulate(actions, put_mode, trigger, channel_mode)
                    if sim is None:
                        ok = False
                        break
                    ch, cc, cs = sim
                    if ch != obs.get('channel') or cc != obs.get('committed_count') or cs != obs.get('committed_sum'):
                        ok = False
                        break
                if ok:
                    consistent.append((put_mode, trigger, channel_mode))

    if not consistent:
        return {"value": None, "unresolved": True}

    actions = context.get('actions', [])
    goal = context.get('goal')
    if goal not in ('channel', 'committed_count', 'committed_sum'):
        return {"value": None, "unresolved": True}

    values = set()
    for put_mode, trigger, channel_mode in consistent:
        sim = simulate(actions, put_mode, trigger, channel_mode)
        if sim is None:
            return {"value": None, "unresolved": True}
        ch, cc, cs = sim
        if goal == 'channel':
            values.add(ch)
        elif goal == 'committed_count':
            values.add(cc)
        else:
            values.add(cs)
    if len(values) == 1:
        return {"value": values.pop(), "unresolved": False}
    else:
        return {"value": None, "unresolved": True}
", "scope": "Infers put conflict mode, trigger presence, and channel definition from calibration receipts, then predicts channel, committed_count, or committed_sum for new action sequences.", "lesson": "The family has 18 members; calibration receipts constrain the combination. Simulate each candidate and check consistency. If all consistent candidates agree on the goal, return that value; otherwise unresolved."}
